head.b:skin:
/* Reset CSS agar Iframe Full Screen tanpa pinggiran putih */
body, html {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden; /* Mencegah munculnya scrollbar ganda */
  background-color: #f1f5f9; /* Warna latar belakang (opsional) */
}
#alima-app {
  width: 100%;
  height: 100%; /* Fallback */
  height: 100dvh; /* Dynamic viewport height untuk mobile modern */
  border: none;
  display: block;
}

body.script:
//

// 1. SILAHKAN MASUKKAN LINK WEB APP GOOGLE SCRIPT ANDA DI SINI
// Pastikan link diakhiri dengan tulisan /exec
const URL_APPS_SCRIPT = "https://script.google.com/macros/s/AKfycbw1o9PIFF3gPDpu8XiNs4KzASVsLsNLCKaA-4nas4hSuyf_wmT67a1otikPhTY2NZWz/exec";

// 2. Membaca URL di atas browser saat ini (Blogger)
const urlParams = new URLSearchParams(window.location.search);
const halamanSekarang = urlParams.get('page') || 'login';

// 3. Masukkan parameter ke dalam Iframe agar Apps Script tahu harus buka halaman apa
document.getElementById('alima-app').src = URL_APPS_SCRIPT + "?page=" + halamanSekarang;

//
